12	declare_rule! {
13	    /// Disallow focused tests.
14	    ///
15	    /// Disabled test are useful when developing and debugging, because it forces the test suite to run only certain tests.
16	    ///
17	    /// However, in pull/merge request, you usually want to run all the test suite.
18	    ///
19	    /// ## Examples
20	    ///
21	    /// ### Invalid
22	    ///
23	    /// ```js,expect_diagnostic
24	    /// describe.only("foo", () => {});
25	    /// ```
26	    ///
27	    /// ```js,expect_diagnostic
28	    /// test.only("foo", () => {});
29	    /// ```
30	    ///
31	    /// ### Valid
32	    /// ```js
33	    /// test("foo", () => {});
34	    /// ```
35	    pub NoFocusedTests {
36	        version: "1.6.0",
37	        name: "noFocusedTests",
38	        recommended: true,
39	        source: RuleSource::EslintJest("no-focused-tests"),
40	        source_kind: RuleSourceKind::Inspired,
41	        fix_kind: FixKind::Unsafe,
42	    }
43	}
