10	declare_rule! {
11	    /// Promotes the usage of `node:assert/strict` over `node:assert`.
12	    ///
13	    /// If you prefer stricter assertions when using the Node.js assertion module, the package `node:assert/strict` exposes a set of alias for stricter assertions.
14	    ///
15	    /// ## Examples
16	    ///
17	    /// ### Invalid
18	    ///
19	    /// ```js,expect_diagnostic
20	    /// import * as assert from "node:assert"
21	    /// ```
22	    ///
23	    /// ### Valid
24	    ///
25	    /// ```js
26	    /// import * as assert from "node:assert/strict"
27	    /// ```
28	    ///
29	    pub UseNodeAssertStrict {
30	        version: "1.6.0",
31	        name: "useNodeAssertStrict",
32	        recommended: false,
33	        fix_kind: FixKind::Safe,
34	    }
35	}
