38	    type Query = Ast<AnyJsImportSpecifierLike>;
39	    type State = JsSyntaxToken;
40	    type Signals = Option<Self::State>;
41	    type Options = ();
42	
43	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
44	        let node = ctx.query();
45	
46	        let text = node.module_name_token()?;
47	        if inner_string_text(&text) == "node:assert" {
48	            return Some(text);
49	        }
50	
51	        None
52	    }
