55	        Some(
56	            RuleDiagnostic::new(
57	                rule_category!(),
58	                ctx.query().module_name_token()?.text_trimmed_range(),
59	                markup! {
60	                    "Use "<Emphasis>"node:assert/strict"</Emphasis>" instead."
61	                },
62	            )
63	            .note(markup! {
64	                "The use of stricter assertion is preferred."
65	            }),
66	        )
67	    }
68	
69	    fn action(ctx: &RuleContext<Self>, module_name: &Self::State) -> Option<JsRuleAction> {
70	        let new_module_name = JsSyntaxToken::new_detached(
71	            JsSyntaxKind::JS_STRING_LITERAL,
