8	declare_rule! {
9	    /// Disallow calling global object properties as functions
10	    ///
11	    /// ECMAScript provides several global objects that are intended to be used as-is.
12	    /// Some of these objects look as if they could be constructors due their capitalization (such as Math and JSON) but will throw an error if you try to execute them as functions.
13	    ///
14	    /// The ECMAScript 5 specification makes it clear that both Math and JSON cannot be invoked:
15	    /// The Math object does not have a [[Call]] internal property; it is not possible to invoke the Math object as a function.
16	    ///
17	    /// The ECMAScript 2015 specification makes it clear that Reflect cannot be invoked:
18	    /// The Reflect object also does not have a [[Call]] internal method; it is not possible to invoke the Reflect object as a function.
19	    ///
20	    /// The ECMAScript 2017 specification makes it clear that Atomics cannot be invoked:
21	    /// The Atomics object does not have a [[Call]] internal method; it is not possible to invoke the Atomics object as a function.
22	    ///
23	    /// And the ECMAScript Internationalization API Specification makes it clear that Intl cannot be invoked:
24	    /// The Intl object does not have a [[Call]] internal method; it is not possible to invoke the Intl object as a function.
25	    ///
26	    /// ## Examples
27	    ///
28	    /// ### Invalid
29	    ///
30	    /// ```js,expect_diagnostic
31	    /// var math = Math();
32	    /// ```
33	    ///
34	    /// ```js,expect_diagnostic
35	    /// var newMath = new Math();
36	    /// ```
37	    ///
38	    /// ```js,expect_diagnostic
39	    /// var json = JSON();
40	    /// ```
41	    ///
42	    /// ```js,expect_diagnostic
43	    /// var newJSON = new JSON();
44	    /// ```
45	    ///
46	    /// ```js,expect_diagnostic
47	    /// var reflect = Reflect();
48	    /// ```
49	    ///
50	    /// ```js,expect_diagnostic
51	    /// var newReflect = new Reflect();
52	    /// ```
53	    ///
54	    /// ```js,expect_diagnostic
55	    /// var atomics = Atomics();
56	    /// ```
57	    ///
58	    /// ```js,expect_diagnostic
59	    /// var newAtomics = new Atomics();
60	    /// ```
61	    ///
62	    /// ```js,expect_diagnostic
63	    /// var intl = Intl();
64	    /// ```
65	    ///
66	    /// ```js,expect_diagnostic
67	    /// var newIntl = new Intl();
68	    /// ```
69	    ///
70	    /// ### Valid
71	    ///
72	    /// ```js
73	    /// function area(r) {
74	    ///     return Math.PI * r * r;
75	    /// }
76	    ///
77	    /// var object = JSON.parse("{}");
78	    ///
79	    /// var value = Reflect.get({ x: 1, y: 2 }, "x");
80	    ///
81	    /// var first = Atomics.load(foo, 0);
82	    ///
83	    /// var segmenterFr = new Intl.Segmenter("fr", { granularity: "word" });
84	    /// ```
85	    ///
86	    pub NoGlobalObjectCalls {
87	        version: "1.0.0",
88	        name: "noGlobalObjectCalls",
89	        source: RuleSource::Eslint("no-obj-calls"),
90	        recommended: true,
91	    }
92	}
