94	impl Rule for NoGlobalObjectCalls {
95	    type Query = Semantic<QueryNode>;
96	    type State = (NonCallableGlobals, TextRange);
97	    type Signals = Option<Self::State>;
98	    type Options = ();
99	
100	    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
101	        let node = ctx.query();
102	        let model = ctx.model();
103	        let callee = node.callee().ok()?.omit_parentheses();
104	        let (reference, name) = global_identifier(&callee)?;
105	        let non_callable = NonCallableGlobals::from_str(name.text()).ok()?;
106	        model
107	            .binding(&reference)
108	            .is_none()
109	            .then_some((non_callable, name.range()))
110	    }
111	
112	    fn diagnostic(
113	        _: &RuleContext<Self>,
114	        (non_callable, range): &Self::State,
115	    ) -> Option<RuleDiagnostic> {
116	        Some(RuleDiagnostic::new(
117	            rule_category!(),
118	            range,
119	            markup! {
120	                <Emphasis>{non_callable.to_string()}</Emphasis>" is not a function."
121	            },
122	        ))
123	    }
124	}
